import React from 'react';
import ReactDOM from 'react-dom';
import '@carbon/react/css/carbon-components.min.css';
import {
  DataTable,
  TableContainer,
  TableToolbar,
  TableToolbarSearch,
  Table,
  TableHead,
  TableRow,
  TableHeader,
  TableBody,
  TableCell,
} from '@carbon/react';

// sample data
const headers = [
  { key: 'name', header: 'Name' },
  { key: 'protocol', header: 'Protocol' },
  { key: 'port', header: 'Port' },
  { key: 'rule', header: 'Rule' },
  { key: 'attached_groups', header: 'Attached groups' },
  { key: 'status', header: 'Status' },
];

const rows = [
  { id: 'a', name: 'Load Balancer 1', protocol: 'HTTP', port: 443, rule: 'Round robin', attached_groups: "Maureen's VM Groups", status: 'Starting' },
  { id: 'b', name: 'Load Balancer 2', protocol: 'HTTP', port: 80, rule: 'DNS delegation', attached_groups: "Andrew's VM Groups", status: 'Active' },
  { id: 'c', name: 'Load Balancer 3', protocol: 'HTTP', port: 3000, rule: 'Round robin', attached_groups: "Kevin's VM Groups", status: 'Disabled' },
];

function App() {
  return (
    <DataTable rows={rows} headers={headers}>
      {({
        rows,
        headers,
        getTableProps,
        getTableContainerProps,
        getToolbarProps,
        onInputChange,
        getHeaderProps,
        getRowProps,
      }) => (
        <TableContainer
          title="DataTable"
          description="With filtering"
          {...getTableContainerProps()}>
          <TableToolbar {...getToolbarProps()}>
            {/* Hover over this icon to see the misalignment */}
            <TableToolbarSearch onChange={onInputChange} />
          </TableToolbar>
          <Table {...getTableProps()}>
            <TableHead>
              <TableRow>
                {headers.map((header) => (
                  <TableHeader key={header.key} {...getHeaderProps({ header })}>
                    {header.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map((row) => (
                <TableRow key={row.id} {...getRowProps({ row })}>
                  {row.cells.map((cell) => (
                    <TableCell key={cell.id}>{cell.value}</TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </DataTable>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
